/**
 * Payment Gateway Configuration
 * Gateway: Stripe
 * Generated by BackendForge
 */

const { env } = require('./env');

// ─── Stripe ─────────────────────────────────────────────────
const Stripe = require('stripe');
const stripe = new Stripe(env.STRIPE_SECRET_KEY, {
  apiVersion: '2024-06-20',
  maxNetworkRetries: 3,
});


/**
 * Get the active payment gateway instance.
 * @param {string} gateway - 'stripe' or 'razorpay' (optional, defaults to env config)
 */
const getPaymentGateway = (gateway) => {
  return { type: 'stripe', client: stripe };
};

module.exports = {
  stripe,
  getPaymentGateway,
};
